import{z as s,x as o,o as n,c as d,q as t,j as l,D as a,d as B,s as i,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"无迹卡尔曼滤波","description":"","frontmatter":{"title":"无迹卡尔曼滤波","date":"2026-09-27T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/unscented-kalman.md","filePath":"quant/unscented-kalman.md","lastUpdated":1791063341000}'),m={name:"quant/unscented-kalman.md"};function D(F,E,p,h,u,C){const A=o("Mermaid");return n(),d("div",null,[E[2]||(E[2]=t('<h1 id="无迹卡尔曼滤波" tabindex="-1">无迹卡尔曼滤波 <a class="header-anchor" href="#无迹卡尔曼滤波" aria-label="Permalink to &quot;无迹卡尔曼滤波&quot;">​</a></h1><div class="epigraph"><p>非线性不一定靠雅可比硬线性化——挑一组确定性采样点穿过非线性函数，加权恢复均值与协方差，二阶矩精度，免求导。</p><footer>—— 据 Julier and Uhlmann, Proceedings of the IEEE, 2004</footer></div><p><a href="/quant/particle-filter">上一课</a>用随机粒子把整个后验搬进内存，代价是粒子和重采样。若非线性温和、后验仍近似单峰，没必要为整张分布买单：无迹变换用 \\(2n+1\\) 个确定性 sigma 点传播一阶二阶矩，把 EKF 的求导环节整个拿掉。它不是粒子滤波的低配版——粒子要的是分布形状，sigma 点要的是矩。本课写选点、传播与增益更新，不写平方根滤波的数值细节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扩展卡尔曼滤波把观测函数在当前均值处泰勒展开取一阶：非线性弱时够用，强时均值被拉偏、协方差被低估；雅可比未必有解析式，数值差分又贵又不稳。跳跃式转移或多峰观测函数下，一切「围绕单点线性化」的方法都失真。粒子滤波接得住但预算高。缺口是中间地带：非线性中等、分布仍像高斯——价差状态、对数波动率这类平滑映射正落在这里。本课不处理状态分量的正性约束，那属于实现层的变换。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(n\\) 维状态取 \\(2n+1\\) 个 sigma 点：一个在均值处，其余沿协方差平方根矩阵的列方向对称展开，尺度由参数组控制。预测步让每个点穿过非线性转移，按权重恢复先验均值与协方差；更新步同样穿过观测函数，用交叉协方差算 Kalman 增益。<span class="marginnote">数字实例：状态维 \\(n=4\\) 时 sigma 点共 \\(2\\times4+1=9\\) 个，一步滤波就是 9 次函数求值加一次 \\(4\\times4\\) 矩阵运算；同等精度下粒子滤波动辄上千粒子、每个还要过转移与似然两个函数——UKF 常省一到两个数量级的浮点预算。参数常取 \\(\\alpha=10^{-3}\\)、\\(\\beta=2\\)，\\(\\lambda=\\alpha^2(n+\\kappa)-n\\) 决定展开宽度。</span></p>',7)),(n(),l(r,null,{default:a(()=>[i(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20MU%5B%22%E5%BD%93%E5%89%8D%E5%9D%87%E5%80%BC%E4%B8%8E%E5%8D%8F%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20SIG%5B%22%E7%94%9F%E6%88%90%202n%2B1%20%E4%B8%AA%20sigma%20%E7%82%B9%22%5D%0A%20%20SIG%20--%3E%20PPROP%5B%22%E6%AF%8F%E4%B8%AA%E7%82%B9%E7%A9%BF%E8%BF%87%E9%9D%9E%E7%BA%BF%E6%80%A7%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20PPROP%20--%3E%20PMOM%5B%22%E5%8A%A0%E6%9D%83%E6%81%A2%E5%A4%8D%E5%85%88%E9%AA%8C%E5%9D%87%E5%80%BC%E5%8D%8F%E6%96%B9%E5%B7%AE%22%5D%0A%20%20PMOM%20--%3E%20OBS%5B%22%E6%96%B0%E8%A7%82%E6%B5%8B%E5%88%B0%E6%9D%A5%22%5D%0A%20%20OBS%20--%3E%20OFUNC%5B%22sigma%20%E7%82%B9%E7%A9%BF%E8%BF%87%E8%A7%82%E6%B5%8B%E5%87%BD%E6%95%B0%22%5D%0A%20%20OFUNC%20--%3E%20KG%5B%22%E4%BA%A4%E5%8F%89%E5%8D%8F%E6%96%B9%E5%B7%AE%E7%AE%97%E5%A2%9E%E7%9B%8A%22%5D%0A%20%20KG%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%E7%8A%B6%E6%80%81%E4%B8%8E%E5%8D%8F%E6%96%B9%E5%B7%AE%22%5D%0A%20%20UPD%20--%3E%20MU%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[B("无迹变换承诺的是矩精度而非分布精度：高斯输入下，任意光滑非线性作用后，sigma 点恢复的均值与协方差精确到二阶泰勒阶，误差只出现在三阶及以上；EKF 的一阶截断误差随曲率增长，且在尖点附近雅可比爆炸。UKF 全程不求导，函数只需可求值——查表式或分段定义的观测模型也能进滤波器。它继承 Kalman 的线性更新律，这一点不因 sigma 点而变。"),e("span",{class:"marginnote"},"常见误区：以为 sigma 点传播后「协方差自动保正、状态自动合规」。错在恢复环节——平方根矩阵把点撒开，加权重构只是线性组合，波动率穿过模型算出负值照样发生。正解是在状态层做对数变换或对结果加投影，不是事后安慰自己。")],-1)),(n(),l(r,null,{default:a(()=>[i(A,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%E7%BB%99%E5%AE%9A%E4%BA%86%E4%BB%80%E4%B9%88%22%5D%20--%3E%20Q1%7B%22%E9%9D%9E%E7%BA%BF%E6%80%A7%E5%BC%BA%E4%B8%94%E5%A4%9A%E5%B3%B0%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20GPF%5B%22%E7%B2%92%E5%AD%90%E6%BB%A4%E6%B3%A2%EF%BC%9A%E4%B9%B0%E6%95%B4%E5%BC%A0%E5%88%86%E5%B8%83%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22%E9%9B%85%E5%8F%AF%E6%AF%94%E6%9C%89%E8%A7%A3%E6%9E%90%E5%BC%8F%E5%90%97%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%9C%89%E4%B8%94%E6%9B%B2%E7%8E%87%E5%B0%8F%22%7C%20EKF%5B%22EKF%20%E4%B9%9F%E5%A4%9F%EF%BC%9A%E4%B8%80%E9%98%B6%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%97%A0%E6%88%96%E6%9B%B2%E7%8E%87%E5%A4%A7%22%7C%20UKF%5B%22UKF%EF%BC%9A%E5%85%8D%E6%B1%82%E5%AF%BC%E7%9A%84%E4%BA%8C%E9%98%B6%E7%9F%A9%22%5D%0A%20%20GPF%20--%3E%20BUD%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E7%B2%92%E5%AD%90%E6%95%B0%E4%B8%8E%E9%87%8D%E9%87%87%E6%A0%B7%22%5D%0A%20%20EKF%20--%3E%20CHEAP%5B%22%E4%BB%A3%E4%BB%B7%E6%9C%80%E4%BD%8E%E4%BD%86%E6%9C%80%E8%84%86%22%5D%0A%20%20UKF%20--%3E%20MID%5B%22%E4%BB%A3%E4%BB%B7%E5%B1%85%E4%B8%AD%E7%B2%BE%E5%BA%A6%E5%B1%85%E4%B8%AD%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>甜区是「平滑非线性加近高斯后验」。强非线性把 sigma 点甩出有效范围，后验双峰时矩匹配直接失义——两种情况都退回粒子滤波。参数敏感：\\(\\lambda\\) 取负时权重出现负值，恢复的协方差可能失正，工程上常配平方根实现兜底。<span class="marginnote">直觉类比：EKF 像在山谷当前落脚点把地形拉成一块平面再滑一步；UKF 像在落脚点周围按固定阵型撒 \\(2n+1\\) 枚探针，各自下坡后重新拟合椭圆。探针撒得再准，恢复的也只是椭圆的圆心与长短轴，不是整张地形图。</span>粒子滤波答不了的便宜题它答了，但它给不出形状，只给矩。下一课把注意力从滤波器挪到状态本身：价差这类量的动力学长什么样——Ornstein–Uhlenbeck 均值回复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UKF 用确定性 sigma 点传播均值与协方差，免雅可比、二阶矩精度。</li><li>\\(2n+1\\) 个点换一整套导数，预算比粒子滤波低一到两个数量级。</li><li>甜区是平滑非线性加近高斯后验；多峰与强非线性退回粒子滤波。</li><li>状态约束与协方差保正要在实现层处理，恢复环节不自动保证。</li><li>出处：Julier and Uhlmann, <em>Proceedings of the IEEE</em>, 2004；Wan and van der Merwe, 2000；Kalman, <em>Journal of Basic Engineering</em>, 1960。</li></ul>',4))])}const P=s(m,[["render",D]]);export{f as __pageData,P as default};
